action.mutation:
mutation CreateLoadCarrier($payload: [LoadCarrierCreatePayloadInput!]!) {
  mutation: createLoadCarrier(payload: $payload) { 
    id
    code
  }
}

mutation UpdateLoadCarrier($payload: [LoadCarrierUpdatePayloadInput!]!) {
  mutation: updateLoadCarrier(payload: $payload) { 
    id
    code
  }
}
